from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]

# Add Identity Vault as an explicit canonical baseline domain. This mirrors the
# existing ORM mapping; tenant-model redesign is a separate security change.
identity_sql = '''-- AI KAREN production baseline: Identity Vault\n-- Schema evolution authority: supabase/migrations only.\n\nCREATE TABLE IF NOT EXISTS identity_providers (\n    id UUID PRIMARY KEY,\n    provider_id VARCHAR(255) NOT NULL UNIQUE,\n    display_name VARCHAR(255) NOT NULL,\n    description TEXT,\n    provider_type VARCHAR(50) NOT NULL,\n    config JSON NOT NULL,\n    icon_url VARCHAR(500),\n    website_url VARCHAR(500),\n    supported_capabilities JSON NOT NULL DEFAULT '[]'::json,\n    enabled BOOLEAN NOT NULL DEFAULT TRUE,\n    is_system BOOLEAN NOT NULL DEFAULT FALSE,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX IF NOT EXISTS idx_identity_providers_enabled ON identity_providers(enabled);\nCREATE INDEX IF NOT EXISTS idx_identity_providers_type ON identity_providers(provider_type);\n\nCREATE TABLE IF NOT EXISTS credentials (\n    id UUID PRIMARY KEY,\n    name VARCHAR(255) NOT NULL,\n    description TEXT,\n    provider_id UUID NOT NULL REFERENCES identity_providers(id) ON DELETE CASCADE,\n    status VARCHAR(50) NOT NULL DEFAULT 'active',\n    credential_type VARCHAR(50) NOT NULL,\n    credential_metadata JSON NOT NULL DEFAULT '{}'::json,\n    masked_hint VARCHAR(255),\n    last_used_at TIMESTAMPTZ,\n    expires_at TIMESTAMPTZ,\n    rotation_interval_hours INTEGER,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    created_by VARCHAR(255)\n);\nCREATE INDEX IF NOT EXISTS idx_credentials_provider ON credentials(provider_id);\nCREATE INDEX IF NOT EXISTS idx_credentials_status ON credentials(status);\nCREATE INDEX IF NOT EXISTS idx_credentials_type ON credentials(credential_type);\nCREATE INDEX IF NOT EXISTS idx_credentials_expires ON credentials(expires_at);\nCREATE INDEX IF NOT EXISTS idx_credentials_last_used ON credentials(last_used_at);\n\nCREATE TABLE IF NOT EXISTS credential_secrets (\n    id UUID PRIMARY KEY,\n    credential_id UUID NOT NULL REFERENCES credentials(id) ON DELETE CASCADE,\n    secret_type VARCHAR(50) NOT NULL,\n    encrypted_value TEXT NOT NULL,\n    encryption_key_id VARCHAR(255),\n    secret_metadata JSON NOT NULL DEFAULT '{}'::json,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX IF NOT EXISTS idx_credential_secrets_credential ON credential_secrets(credential_id);\nCREATE INDEX IF NOT EXISTS idx_credential_secrets_type ON credential_secrets(secret_type);\n\nCREATE TABLE IF NOT EXISTS external_accounts (\n    id UUID PRIMARY KEY,\n    provider_id UUID NOT NULL REFERENCES identity_providers(id) ON DELETE CASCADE,\n    account_identifier VARCHAR(255) NOT NULL,\n    display_name VARCHAR(255),\n    account_metadata JSON NOT NULL DEFAULT '{}'::json,\n    capabilities JSON NOT NULL DEFAULT '[]'::json,\n    is_active BOOLEAN NOT NULL DEFAULT TRUE,\n    last_verified_at TIMESTAMPTZ,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    CONSTRAINT uq_external_accounts_provider_identifier UNIQUE(provider_id, account_identifier)\n);\nCREATE INDEX IF NOT EXISTS idx_external_accounts_provider ON external_accounts(provider_id);\nCREATE INDEX IF NOT EXISTS idx_external_accounts_identifier ON external_accounts(account_identifier);\nCREATE INDEX IF NOT EXISTS idx_external_accounts_active ON external_accounts(is_active);\n\nCREATE TABLE IF NOT EXISTS credential_bindings (\n    id UUID PRIMARY KEY,\n    credential_id UUID NOT NULL REFERENCES credentials(id) ON DELETE CASCADE,\n    external_account_id UUID NOT NULL REFERENCES external_accounts(id) ON DELETE CASCADE,\n    is_active BOOLEAN NOT NULL DEFAULT TRUE,\n    is_primary BOOLEAN NOT NULL DEFAULT FALSE,\n    binding_metadata JSON NOT NULL DEFAULT '{}'::json,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    CONSTRAINT uq_external_account_primary UNIQUE(external_account_id, is_primary)\n);\nCREATE INDEX IF NOT EXISTS idx_credential_bindings_credential ON credential_bindings(credential_id);\nCREATE INDEX IF NOT EXISTS idx_credential_bindings_account ON credential_bindings(external_account_id);\nCREATE INDEX IF NOT EXISTS idx_credential_bindings_active ON credential_bindings(is_active);\n\nCREATE TABLE IF NOT EXISTS account_sessions (\n    id UUID PRIMARY KEY,\n    credential_id UUID NOT NULL REFERENCES credentials(id) ON DELETE CASCADE,\n    external_account_id UUID NOT NULL REFERENCES external_accounts(id) ON DELETE CASCADE,\n    session_token VARCHAR(255) NOT NULL UNIQUE,\n    access_token TEXT,\n    refresh_token TEXT,\n    token_type VARCHAR(50) NOT NULL,\n    expires_at TIMESTAMPTZ,\n    scopes JSON NOT NULL DEFAULT '[]'::json,\n    session_metadata JSON NOT NULL DEFAULT '{}'::json,\n    ip_address VARCHAR(45),\n    user_agent VARCHAR(500),\n    is_active BOOLEAN NOT NULL DEFAULT TRUE,\n    last_used_at TIMESTAMPTZ,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX IF NOT EXISTS idx_account_sessions_credential ON account_sessions(credential_id);\nCREATE INDEX IF NOT EXISTS idx_account_sessions_account ON account_sessions(external_account_id);\nCREATE INDEX IF NOT EXISTS idx_account_sessions_active ON account_sessions(is_active);\nCREATE INDEX IF NOT EXISTS idx_account_sessions_expires ON account_sessions(expires_at);\nCREATE INDEX IF NOT EXISTS idx_account_sessions_token ON account_sessions(session_token);\n\nCREATE TABLE IF NOT EXISTS auth_grants (\n    id UUID PRIMARY KEY,\n    credential_id UUID NOT NULL REFERENCES credentials(id) ON DELETE CASCADE,\n    provider_id UUID NOT NULL REFERENCES identity_providers(id) ON DELETE CASCADE,\n    grant_type VARCHAR(50) NOT NULL,\n    authorization_code VARCHAR(255),\n    access_token TEXT,\n    refresh_token TEXT,\n    scopes JSON NOT NULL DEFAULT '[]'::json,\n    expires_at TIMESTAMPTZ,\n    redirect_uri VARCHAR(500),\n    state VARCHAR(255),\n    code_challenge VARCHAR(255),\n    code_challenge_method VARCHAR(50),\n    is_completed BOOLEAN NOT NULL DEFAULT FALSE,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX IF NOT EXISTS idx_auth_grants_credential ON auth_grants(credential_id);\nCREATE INDEX IF NOT EXISTS idx_auth_grants_provider ON auth_grants(provider_id);\nCREATE INDEX IF NOT EXISTS idx_auth_grants_completed ON auth_grants(is_completed);\nCREATE INDEX IF NOT EXISTS idx_auth_grants_expires ON auth_grants(expires_at);\n\nCREATE TABLE IF NOT EXISTS token_leases (\n    id UUID PRIMARY KEY,\n    credential_id UUID NOT NULL REFERENCES credentials(id) ON DELETE CASCADE,\n    lease_token VARCHAR(255) NOT NULL UNIQUE,\n    access_token TEXT,\n    expires_at TIMESTAMPTZ NOT NULL,\n    scopes JSON NOT NULL DEFAULT '[]'::json,\n    lease_metadata JSON NOT NULL DEFAULT '{}'::json,\n    is_active BOOLEAN NOT NULL DEFAULT TRUE,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX IF NOT EXISTS idx_token_leases_credential ON token_leases(credential_id);\nCREATE INDEX IF NOT EXISTS idx_token_leases_active ON token_leases(is_active);\nCREATE INDEX IF NOT EXISTS idx_token_leases_expires ON token_leases(expires_at);\nCREATE INDEX IF NOT EXISTS idx_token_leases_token ON token_leases(lease_token);\n\nCREATE TABLE IF NOT EXISTS login_attempts (\n    id UUID PRIMARY KEY,\n    credential_id UUID NOT NULL REFERENCES credentials(id) ON DELETE CASCADE,\n    external_account_id UUID REFERENCES external_accounts(id) ON DELETE CASCADE,\n    attempt_type VARCHAR(50) NOT NULL,\n    status VARCHAR(50) NOT NULL,\n    error_code VARCHAR(100),\n    error_message TEXT,\n    ip_address VARCHAR(45),\n    user_agent VARCHAR(500),\n    timestamp TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    attempt_metadata JSON NOT NULL DEFAULT '{}'::json\n);\nCREATE INDEX IF NOT EXISTS idx_login_attempts_credential ON login_attempts(credential_id);\nCREATE INDEX IF NOT EXISTS idx_login_attempts_account ON login_attempts(external_account_id);\nCREATE INDEX IF NOT EXISTS idx_login_attempts_status ON login_attempts(status);\nCREATE INDEX IF NOT EXISTS idx_login_attempts_timestamp ON login_attempts(timestamp);\n\nCREATE TABLE IF NOT EXISTS credential_audit_events (\n    id UUID PRIMARY KEY,\n    tenant_id UUID NOT NULL,\n    user_id VARCHAR(255) NOT NULL,\n    credential_id UUID NOT NULL REFERENCES credentials(id) ON DELETE CASCADE,\n    account_id UUID REFERENCES external_accounts(id) ON DELETE CASCADE,\n    provider_id UUID REFERENCES identity_providers(id) ON DELETE CASCADE,\n    event_type VARCHAR(50) NOT NULL,\n    action VARCHAR(100) NOT NULL,\n    resource_type VARCHAR(50) NOT NULL,\n    resource_id VARCHAR(255),\n    correlation_id VARCHAR(255),\n    ip_address VARCHAR(45),\n    user_agent VARCHAR(500),\n    audit_metadata JSON NOT NULL DEFAULT '{}'::json,\n    timestamp TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX IF NOT EXISTS idx_credential_audit_events_tenant ON credential_audit_events(tenant_id);\nCREATE INDEX IF NOT EXISTS idx_credential_audit_events_user ON credential_audit_events(user_id);\nCREATE INDEX IF NOT EXISTS idx_credential_audit_events_credential ON credential_audit_events(credential_id);\nCREATE INDEX IF NOT EXISTS idx_credential_audit_events_event ON credential_audit_events(event_type);\nCREATE INDEX IF NOT EXISTS idx_credential_audit_events_timestamp ON credential_audit_events(timestamp);\nCREATE INDEX IF NOT EXISTS idx_credential_audit_events_correlation ON credential_audit_events(correlation_id);\n'''
identity_path = ROOT / "supabase/migrations/20260827070000_07_identity_vault.sql"
identity_path.write_text(identity_sql)

# Database client must never mutate primary PostgreSQL schema.
path = ROOT / "src/ai_karen_engine/database/client.py"
text = path.read_text()
start = text.find("    def drop_tables(self):")
end = text.find("    def get_session(self)", start)
if start == -1 or end == -1:
    raise SystemExit("drop_tables block not found")
text = text[:start] + '''    def drop_tables(self):\n        \"\"\"Compatibility no-op. Destructive schema operations are deployment-owned.\"\"\"\n        logger.warning(\"DatabaseClient.drop_tables() is disabled; use controlled recovery tooling.\")\n        return None\n\n''' + text[end:]
start = text.find("    async def create_tables_async(self):")
end = text.find("\n\n# Multi-tenant database client class", start)
if start == -1 or end == -1:
    raise SystemExit("create_tables_async block not found")
text = text[:start] + '''    async def create_tables_async(self):\n        \"\"\"Compatibility no-op. Schema creation is owned by Supabase migrations.\"\"\"\n        logger.warning(\"DatabaseClient.create_tables_async() is disabled; apply Supabase migrations before startup.\")\n        return None\n''' + text[end:]
start = text.find("    def create_persona_tables(self) -> None:")
end = text.find("    def create_tenant_schema", start)
if start == -1 or end == -1:
    raise SystemExit("create_persona_tables block not found")
text = text[:start] + '''    def create_persona_tables(self) -> None:\n        \"\"\"Compatibility no-op. Persona tables are part of the Supabase baseline.\"\"\"\n        logger.warning(\"create_persona_tables() is disabled; persona schema is migration-owned.\")\n        return None\n\n''' + text[end:]
path.write_text(text)

# Identity Vault ORM module becomes mappings + read-only validation only.
path = ROOT / "src/ai_karen_engine/database/identity_vault_schema.py"
text = path.read_text()
start = text.find("class IdentityVaultSchema:")
if start == -1:
    raise SystemExit("IdentityVaultSchema not found")
replacement = '''class IdentityVaultSchema:\n    \"\"\"Read-only validator for migration-owned Identity Vault tables.\"\"\"\n\n    REQUIRED_TABLES = (\n        \"identity_providers\", \"credentials\", \"credential_secrets\",\n        \"external_accounts\", \"credential_bindings\", \"account_sessions\",\n        \"auth_grants\", \"token_leases\", \"login_attempts\",\n        \"credential_audit_events\",\n    )\n\n    def __init__(self, database_url: str):\n        self.database_url = database_url\n        self.logger = logging.getLogger(__name__)\n\n    def validate_schema(self, engine) -> bool:\n        \"\"\"Return whether all migration-owned Identity Vault tables exist.\"\"\"\n        from sqlalchemy import inspect\n        try:\n            existing = set(inspect(engine).get_table_names())\n            missing = set(self.REQUIRED_TABLES) - existing\n            if missing:\n                self.logger.error(\"Missing Identity Vault tables: %s\", sorted(missing))\n                return False\n            return True\n        except Exception as exc:\n            self.logger.error(\"Identity Vault schema validation failed: %s\", exc)\n            return False\n\n\n# Schema creation is intentionally absent. Supabase migrations own DDL.\n'''
path.write_text(text[:start] + replacement)

# Identity Vault startup verifies tables instead of creating them.
path = ROOT / "src/ai_karen_engine/services/identity_vault/credential_vault_service.py"
text = path.read_text()
old = '''    async def _ensure_database_tables(self) -> None:\n        \"\"\"Ensure database tables exist.\"\"\"\n        if self._tables_ensured:\n            return\n        \n        try:\n            client = self._get_db_client()\n            await client.create_tables_async()\n            self._tables_ensured = True\n            logger.info(\"Database tables verified/created successfully\")\n        except Exception as e:\n            logger.error(f\"Failed to ensure database tables: {e}\")\n            # Don't re-raise here to allow service to start even if DB is not ready\n'''
new = '''    async def _ensure_database_tables(self) -> None:\n        \"\"\"Verify migration-owned Identity Vault tables exist; never create schema.\"\"\"\n        if self._tables_ensured:\n            return\n        client = self._get_db_client()\n        required = {\n            \"identity_providers\", \"credentials\", \"credential_secrets\",\n            \"external_accounts\", \"credential_bindings\", \"account_sessions\",\n            \"auth_grants\", \"token_leases\", \"login_attempts\",\n            \"credential_audit_events\",\n        }\n        async with client.get_async_session() as session:\n            result = await session.execute(\n                select(func.count()).select_from(\n                    text(\"information_schema.tables\")\n                ).where(\n                    text(\"table_schema = 'public' AND table_name = ANY(:tables)\")\n                ),\n                {\"tables\": list(required)},\n            )\n            present_count = int(result.scalar() or 0)\n        if present_count != len(required):\n            raise RuntimeError(\n                \"Identity Vault schema is incomplete. Apply canonical Supabase migrations before startup.\"\n            )\n        self._tables_ensured = True\n        logger.info(\"Identity Vault migration-owned tables verified\")\n'''
if old not in text:
    raise SystemExit("credential vault ensure block not found")
path.write_text(text.replace(old, new))

# Baseline docs include Identity Vault stage.
path = ROOT / "docs/database/BASELINE_2026_08.md"
text = path.read_text()
needle = "| `06_auth_refresh_history` | `auth_refresh_token_history` |\n"
if needle in text and "07_identity_vault" not in text:
    text = text.replace(needle, needle + "| `07_identity_vault` | Existing Identity Vault ORM schema moved under canonical migration authority |\n")
path.write_text(text)

# Supabase smoke now expects seven domain stages.
path = ROOT / "tests/supabase_platform_smoke.py"
text = path.read_text().replace("assert len(migrations) == 6", "assert len(migrations) == 7")
text = text.replace('assert migrations[-1].name.endswith("06_auth_refresh_history.sql")', 'assert migrations[-1].name.endswith("07_identity_vault.sql")')
path.write_text(text)

# Strong source guard for primary database package and vault startup.
for scan in [ROOT / "src/ai_karen_engine/database", ROOT / "src/ai_karen_engine/services/identity_vault"]:
    for py in scan.rglob("*.py"):
        content = py.read_text(errors="ignore")
        if "metadata.create_all" in content or "metadata.drop_all" in content:
            raise SystemExit(f"runtime schema mutation survived: {py.relative_to(ROOT)}")

service_text = (ROOT / "src/ai_karen_engine/services/identity_vault/credential_vault_service.py").read_text()
if "create_tables_async()" in service_text:
    raise SystemExit("Identity Vault still creates tables")

print("final DB runtime schema authority closure complete")
